document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("profile-form");e&&e.addEventListener("submit",function(t){t.preventDefault(),(t=new FormData(this)).append("action","updateProfile"),fetch("../controllers/ProfileController.php",{method:"POST",body:t}).then(e=>e.json()).then(e=>{e.success?Toastify({text:e.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast():Toastify({text:e.message||"An unknown error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})});const t=document.getElementById("password-form");t&&t.addEventListener("submit",function(e){e.preventDefault(),(e=new FormData(this)).append("action","updatePassword"),fetch("../controllers/ProfileController.php",{method:"POST",body:e}).then(e=>e.json()).then(s=>{s.success?(Toastify({text:s.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast(),t.reset()):Toastify({text:s.message||"An unknown error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})})});
